<section class="panel"><div class="panel-head"><div><span class="eyebrow">FIXTURES & RESULTS</span><h2>Match schedule</h2></div><a class="btn" href="index.php?route=matches/form">+ Schedule match</a></div>
<?php if(!$matches): ?><p class="empty">No matches added yet.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>Opponent</th><th>Date</th><th>Venue</th><th>Competition</th><th>Score</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($matches as $m): ?><tr><td><b><?= e($m['opponent']) ?></b></td><td><?= e(date('d M Y H:i',strtotime($m['match_date']))) ?></td><td><?= e($m['venue']) ?></td><td><?= e($m['competition']) ?></td><td><?= $m['our_score']===null?'—':e($m['our_score'].' - '.$m['opponent_score']) ?></td><td><span class="status <?= e($m['status']) ?>"><?= e(ucfirst($m['status'])) ?></span></td><td class="actions"><a href="index.php?route=matches/form&id=<?= e($m['id']) ?>">Edit</a><form method="post" action="index.php?route=matches/delete" data-confirm="Delete this match?"><?= csrf_field() ?><input type="hidden" name="id" value="<?= e($m['id']) ?>"><button class="danger-link">Delete</button></form></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>